const rules = {
  'tribunus-schema-version': {
    message: 'Schema must use draft/2020-12',
    given: '$',
    then: {
      field: '$schema',
      function: 'defined'
    }
  },
  'tribunus-id-domain': {
    message: '$id must use tribunus.dev domain',
    given: '$',
    then: {
      field: '$id',
      function: 'pattern',
      functionOptions: {
        match: '^https://tribunus\\.dev/'
      }
    }
  },
  'tribunus-required-metadata': {
    message: 'Schema must have $schema, $id, title, description',
    given: '$',
    then: {
      field: 'title',
      function: 'truthy'
    }
  }
};

import Ajv from 'ajv';
import addFormats from 'ajv-formats';

const ajv = new Ajv({
  strictSchema: true,
  strictNumbers: true,
  strictRequired: true,
  strictTypes: true,
  strictTuples: true,
  allErrors: false
});
addFormats(ajv);

// Compile once, reuse
const validate = ajv.compile(schema);
const valid = validate(data);

import { compileFromFile } from 'json-schema-to-typescript';

const types = await compileFromFile('schemas/my-schema.schema.json', {
  cwd: 'schemas',
  style: { singleQuote: true, semi: true },
  additionalProperties: false,
  unreachableDefinitions: false
});

await write('src/generated/my-schema.ts', types);
